      }
    }

  Supports negation.

  </tr>
  <tr>
    <th>$lt</th>
    <th>

  Less than

    {
      "time.start": {
        "$lt": "2018-08-28T05:56"
      }
    }

  </tr>
  <tr>
    <th>$gt</th>
    <th>

  Greater than

    {
      "ageRange.maxValue": {
        "$gt": "50"
      }
